#!/usr/bin/env node
// Packs the files HTML Server reads at run time (package.json, public/, gallery/) into
// cloudflare/files.generated.js, because a Cloudflare Worker has no disk of ours to
// read them from (src/files.js reads them from here there). Wrangler runs this before
// every build and deploy ([build] in wrangler.toml); the output is not committed.
import { readdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = fileURLToPath(new URL('..', import.meta.url));
const INCLUDE = ['package.json', 'public', 'gallery'];
const SKIP = /(^|\/)\.|\.txt$/; // dotfiles; the font licences are shipped in the repo, not needed at run time

const files = {};
const add = (path) => {
  const rel = relative(ROOT, path).split('\\').join('/');
  if (SKIP.test(rel)) return;
  if (statSync(path).isDirectory()) return readdirSync(path).forEach((f) => add(join(path, f)));
  files[rel] = { data: readFileSync(path).toString('base64'), mtime: Math.round(statSync(path).mtimeMs) };
};
INCLUDE.forEach((p) => add(join(ROOT, p)));

writeFileSync(new URL('files.generated.js', import.meta.url),
  `// Generated by cloudflare/bundle-files.js: do not edit, and don't commit.\nglobalThis.__HTML_SERVER_FILES__ = ${JSON.stringify(files)};\n`);
const kb = Object.values(files).reduce((n, f) => n + f.data.length, 0) / 1024;
console.log(`bundled ${Object.keys(files).length} files (${Math.round(kb)} KB) into cloudflare/files.generated.js`);
